// expect: exit 0
// screen: 0 vowel
// screen: 1 space
// screen: 2 other
void show(int c)
{
    switch (c) {
    case 'a': case 'e': case 'i': case 'o': case 'u':
        puts("vowel");
        break;
    case ' ':
        puts("space");
        break;
    default:
        puts("other");
    }
}
int main(void)
{
    cls();
    show('e');
    show(' ');
    show('x');
    return 0;
}
